/*
 * A002289  Weight distribution of [ 23,12,7 ] binary perfect Golay code.
 * https://oeis.org/A002289
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, fini, full, nice
 * Formula:   a(n) = number of codewords of Hamming weight n in the [23,12,7]
 *            binary cyclic Golay code generated by g(x) =
 *            x^11+x^10+x^6+x^5+x^4+x^2+1, found by enumerating all 2^12
 *            codewords m(x)*g(x) over GF(2); a(n) = 0 for n > 23
 * Range:     u8 n <= 7, u16 n <= 23, u32 n <= 23, u64 n <= 23, u128 n <= 23,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

static uint32_t a002289_cnt[24];
static int a002289_done = 0;

static void a002289_init(void) {
    const uint32_t g = 0xC75u;
    uint32_t m;
    int i;
    for (i = 0; i < 24; i++) a002289_cnt[i] = 0;
    for (m = 0; m < 4096u; m++) {
        uint32_t c = 0, x = m;
        int w = 0, s = 0;
        while (x) {
            if (x & 1u) c ^= g << s;
            x >>= 1;
            s++;
        }
        while (c) {
            w += (int)(c & 1u);
            c >>= 1;
        }
        a002289_cnt[w]++;
    }
    a002289_done = 1;
}

seq_t a(idx_t n) {
    if (!a002289_done) a002289_init();
    if (n > 23) return (seq_t)0;
    return (seq_t)a002289_cnt[(int)n];
}
